"""Build a local reading preview from the article's Markdown source."""
from pathlib import Path
import html
import re
import markdown

ROOT = Path(__file__).resolve().parent.parent
source = (ROOT / '03-正文.md').read_text(encoding='utf-8')
renderer = markdown.Markdown(extensions=['tables', 'fenced_code', 'toc'],
    extension_configs={'toc': {'toc_depth': '2-2'}})
body = renderer.convert(source)
body = re.sub(r'<h1[^>]*>.*?</h1>', '', body, count=1, flags=re.S)
body = body.replace('<table>', '<div class="table-scroll"><table>')
body = body.replace('</table>', '</table></div>')
title = source.splitlines()[0].removeprefix('# ')
style = """
:root{--ink:#18243b;--muted:#65738b;--line:#e2e8f2;--violet:#6754d8}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:28px}body{margin:0;background:#f2f5fa;color:var(--ink);font-family:Segoe UI,Microsoft YaHei,sans-serif;line-height:1.95}.masthead{background:#090e24;color:#aebbdc;padding:16px max(28px,calc((100vw - 1200px)/2));font-size:13px;letter-spacing:1px}.masthead b{color:white}.hero{max-width:1200px;margin:46px auto 32px;padding:0 30px}.eyebrow{font-size:12px;letter-spacing:2px;color:var(--violet);font-weight:700}.hero h1{font-size:clamp(30px,4vw,46px);line-height:1.35;letter-spacing:-1px;margin:14px 0}.meta{font-size:13px;color:var(--muted)}.layout{max-width:1200px;padding:0 30px 70px;margin:auto;display:grid;grid-template-columns:minmax(0,900px) 210px;gap:34px;align-items:start}article{min-width:0;background:white;border:1px solid var(--line);border-radius:18px;padding:38px 44px;box-shadow:0 8px 30px #29376006}article>p:first-child{font-size:19px;line-height:1.8;margin-top:0}p{margin:17px 0}h2{margin:58px 0 20px;font-size:26px;line-height:1.5;border-top:1px solid var(--line);padding-top:34px}h3{font-size:21px;line-height:1.5;margin:34px 0 14px}strong{font-weight:650;color:#202b48}img{display:block;width:100%;height:auto;border-radius:12px;margin:24px auto}p:has(>em:only-child){font-size:13px;line-height:1.7;color:var(--muted);text-align:center;margin-top:-10px}blockquote{margin:24px 0;border-left:4px solid #8977ed;padding:14px 20px;background:#f5f3ff;border-radius:0 9px 9px 0;color:#4d4d71}blockquote p{margin:0}code{font-family:Cascadia Code,Consolas,monospace;font-size:.87em;background:#f0f3f9;color:#545094;border-radius:5px;padding:2px 5px;overflow-wrap:anywhere}pre{overflow:auto;background:#10182c;border-radius:12px;color:#dce9ff;padding:23px 22px;line-height:1.75;font-size:13px}pre code{background:transparent;padding:0;color:inherit;white-space:pre;overflow-wrap:normal}.table-scroll{overflow-x:auto;margin:24px 0;border:1px solid var(--line);border-radius:11px}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.7}th{background:#edf1f8;color:#40506d;text-align:left;font-weight:650;white-space:nowrap}td,th{padding:12px 14px;border-bottom:1px solid var(--line);vertical-align:top}tr:last-child td{border-bottom:none}td{min-width:130px}td:last-child{overflow-wrap:anywhere}td code{font-size:12px}aside{position:sticky;top:24px;font-size:12px;color:var(--muted);padding-top:12px}aside h4{margin:0 0 12px;color:#3b4661}.toc ul{list-style:none;padding:0;margin:0}.toc li{line-height:1.6;margin:12px 0}.toc a{color:var(--muted);text-decoration:none;display:block;border-left:2px solid transparent;padding-left:12px}.toc a:hover{color:var(--violet);border-color:var(--violet)}.review-tip{border-top:1px solid var(--line);margin-top:24px;padding-top:18px;font-size:12px;line-height:1.75}footer{text-align:center;padding:0 20px 40px;font-size:12px;color:var(--muted)}@media(max-width:1000px){.layout{grid-template-columns:minmax(0,1fr)}aside{display:none}}@media(max-width:600px){.hero{padding:0 18px;margin-top:28px}.hero h1{font-size:29px}.layout{padding:0 10px 30px}article{padding:22px 18px;border-radius:12px}h2{font-size:23px;margin-top:44px}h3{font-size:19px}pre{font-size:11px;padding:20px 13px}td,th{padding:10px}img{border-radius:9px}.masthead{padding:12px 18px}}@media print{.masthead,aside{display:none}.hero,.layout{padding:0;max-width:none;margin:0;display:block}article{border:none;box-shadow:none;padding:0}h2{break-after:avoid}img,pre,table{break-inside:avoid}}
"""
style += 'article a{color:#5145af;text-underline-offset:3px;overflow-wrap:anywhere}article a:hover{color:#352878}a code{color:inherit}'
page = f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><style>{style}</style></head><body><div class="masthead"><b>椒颜皮皮虾</b> / ROCm × C# / ARTICLE 001</div><header class="hero"><div class="eyebrow">OPEN SOURCE · RELEASE 1.0.0</div><h1>{html.escape(title)}</h1><div class="meta">Guojin Yan · 2026-11-21 · v8，四案例真实数据复跑与路径修正</div></header><main class="layout"><article>{body}</article><aside><h4>本篇内容</h4>{renderer.toc}<div class="review-tip">七章正文 · 七个正式版 NuGet 包<br>概念配图与实际验证结果分别标注。<br>Markdown 正文为编辑主文件。</div></aside></main><footer>ROCm 系列 · 文章 001 · 本地阅读预览</footer></body></html>'''
(ROOT / '03-正文预览.html').write_text(page, encoding='utf-8', newline='\n')
print('Built responsive local article preview.')
